49	/**
50	 * Emits a warning feedback event only once per process.
51	 */
52	function emitWarningOnce(message: string): void {
53	  if (!emittedWarnings.has(message)) {
54	    coreEvents.emitFeedback('warning', message);
55	    emittedWarnings.add(message);
56	  }
57	}
