174	/**
175	 * Formats a policy file error for console logging.
176	 */
177	export function formatPolicyError(error: PolicyFileError): string {
178	  const tierLabel = error.tier.toUpperCase();
179	  const severityLabel = error.severity === 'warning' ? 'warning' : 'error';
180	  let message = `[${tierLabel}] Policy file ${severityLabel} in ${error.fileName}:\n`;
181	  message += `  ${error.message}`;
182	  if (error.details) {
183	    message += `\n${error.details}`;
184	  }
185	  if (error.suggestion) {
186	    message += `\n  Suggestion: ${error.suggestion}`;
187	  }
188	  return message;
189	}
