42	function isWildcardPattern(name: string): boolean {
43	  return name === '*' || name.includes('*');
44	}
45	
46	/**
47	 * Checks if a tool call matches a wildcard pattern.
48	 * Supports global (*) and the explicit MCP (*mcp_serverName_**) format.
49	 */
50	function matchesWildcard(
51	  pattern: string,
52	  toolName: string,
53	  serverName: string | undefined,
54	): boolean {
55	  if (pattern === '*') {
56	    return true;
57	  }
58	
59	  if (pattern === `${MCP_TOOL_PREFIX}*`) {
60	    return serverName !== undefined;
61	  }
62	
63	  if (pattern.startsWith(MCP_TOOL_PREFIX) && pattern.endsWith('_*')) {
64	    const expectedServerName = pattern.slice(MCP_TOOL_PREFIX.length, -2);
65	    // 1. Must be an MCP tool call (has serverName)
66	    // 2. Server name must match
67	    // 3. Tool name must be properly qualified by that server
68	    if (serverName === undefined || serverName !== expectedServerName) {
69	      return false;
70	    }
71	    return toolName.startsWith(`${MCP_TOOL_PREFIX}${expectedServerName}_`);
72	  }
73	
74	  // Not a recognized wildcard pattern, fallback to exact match just in case
75	  return toolName === pattern;
76	}
