78	function ruleMatches(
79	  rule: PolicyRule | SafetyCheckerRule,
80	  toolCall: FunctionCall,
81	  stringifiedArgs: string | undefined,
82	  serverName: string | undefined,
83	  currentApprovalMode: ApprovalMode,
84	  nonInteractive: boolean,
85	  toolAnnotations?: Record<string, unknown>,
86	  subagent?: string,
87	): boolean {
88	  // Check if rule applies to current approval mode
89	  if (rule.modes && rule.modes.length > 0) {
90	    if (!rule.modes.includes(currentApprovalMode)) {
91	      return false;
92	    }
93	  }
94	
95	  // Check subagent if specified (only for PolicyRule, SafetyCheckerRule doesn't have it)
96	  if ('subagent' in rule && rule.subagent !== undefined) {
97	    if (rule.subagent !== subagent) {
98	      return false;
99	    }
100	  }
101	
102	  // Strictly enforce mcpName identity if the rule dictates it
103	  if (rule.mcpName !== undefined) {
104	    if (rule.mcpName === '*') {
105	      // Rule requires it to be ANY MCP tool
106	      if (serverName === undefined) return false;
107	    } else {
108	      // Rule requires it to be a specific MCP server
109	      if (serverName !== rule.mcpName) return false;
110	    }
111	  }
112	
113	  // Check tool name if specified
114	  if (rule.toolName !== undefined) {
115	    // Support wildcard patterns: "mcp_serverName_*" matches "mcp_serverName_anyTool"
116	    if (rule.toolName === '*') {
117	      // Match all tools
118	    } else if (isWildcardPattern(rule.toolName)) {
119	      if (
120	        !toolCall.name ||
121	        !matchesWildcard(rule.toolName, toolCall.name, serverName)
122	      ) {
123	        return false;
124	      }
125	    } else if (toolCall.name !== rule.toolName) {
126	      // If names don't match exactly, check for MCP short/full name mismatches
127	      let mcpMatch = false;
128	      if (serverName && toolCall.name) {
129	        // Case 1: Rule uses short name + mcpName -> match FQN tool call
130	        if (rule.mcpName && !isMcpToolName(rule.toolName)) {
131	          if (
132	            toolCall.name === formatMcpToolName(rule.mcpName, rule.toolName)
133	          ) {
134	            mcpMatch = true;
135	          }
136	        }
137	        // Case 2: Rule uses FQN -> match short tool call (qualified by serverName)
138	        if (!mcpMatch && isMcpToolName(rule.toolName)) {
139	          if (rule.toolName === formatMcpToolName(serverName, toolCall.name)) {
140	            mcpMatch = true;
141	          }
142	        }
143	      }
144	
145	      if (!mcpMatch) {
146	        return false;
147	      }
148	    }
149	  }
150	
151	  // Check annotations if specified
152	  if (rule.toolAnnotations) {
153	    if (!toolAnnotations) {
154	      return false;
155	    }
156	    for (const [key, value] of Object.entries(rule.toolAnnotations)) {
157	      if (toolAnnotations[key] !== value) {
158	        return false;
159	      }
160	    }
161	  }
162	
163	  // Check args pattern if specified
164	  if (rule.argsPattern) {
165	    // If rule has an args pattern but tool has no args, no match
166	    if (!toolCall.args) {
167	      return false;
168	    }
169	    // Use stable JSON stringification with sorted keys to ensure consistent matching
170	    if (
171	      stringifiedArgs === undefined ||
172	      !rule.argsPattern.test(stringifiedArgs)
173	    ) {
174	      return false;
175	    }
176	  }
177	
178	  // Check interactive if specified
179	  if ('interactive' in rule && rule.interactive !== undefined) {
180	    if (rule.interactive && nonInteractive) {
181	      return false;
182	    }
183	    if (!rule.interactive && !nonInteractive) {
184	      return false;
185	    }
186	  }
187	
188	  return true;
189	}
